window.docContents[195].resolve({"/Smallstep/#Type-Systems--Smallstep___-Small-step-Operational-Semantics--Multi-Step-Reduction--Normal-Forms-Again":{"contents":"If t reduces to t' in zero or more steps and t' is a normal form, we\n   say that \"t' is a normal form of t.\"\n\ndef IsNormalFormOf {α : Type} (R : Relation α) (t t' : α) : Prop :=\n  Multi R t t' ∧ IsNormalForm R t'\n\n\n\n\nWhen R is deterministic (as for our language's semantics), its normal form is unique.\n\nYOTAM: The proof can be given for the general case, i.e. that\n   determinism of a relation implies the determinism of its IsNormalFormOf\n   induced counterpart.  BCP 23: That would be a nice improvement.\n\n\n\ntheorem normal_forms_unique :\n    Deterministic (IsNormalFormOf Step) := by\n  -- We recommend using this initial setup as-is!\n  intro x y₁ y₂ p₁ p₂\n  obtain ⟨p₁₁, p₁₂⟩ := p₁\n  obtain ⟨p₂₁, p₂₂⟩ := p₂\n  sorry\n\n\n\n\nThe Step relation is normalizing: every term reaches a normal form in\na finite number of steps. Determinism guarantees that normal form is unique.\nunique.\n\ndef Normalizing {α : Type} (R : Relation α) : Prop :=\n  ∀ t, ∃ t', IsNormalFormOf R t t'\n\ntheorem multistep_congr_1 (t₁ t₁' t₂ : Tm) (h : t₁ ⟶* t₁') :\n    (.p t₁ t₂) ⟶* (.p t₁' t₂) := by\n  induction h with\n  | refl x => exact .refl _\n  | step x y z h₁ h₂ ih =>\n      apply Multi.step (y := .p y t₂)\n      · apply Step.plusLeft\n        exact h₁\n      · exact ih\n\n\ntheorem multistep_congr_2 (v₁ t₂ t₂' : Tm) (hv : IsValue v₁)\n    (h : t₂ ⟶* t₂') :\n    (.p v₁ t₂) ⟶* (.p v₁ t₂') := by\n  sorry\n\n\n\n\ntheorem step_normalizing : Normalizing Step := by\n  intro t\n  induction t with\n  | c n =>\n      exists .c n\n      constructor\n      · apply Multi.refl\n      · apply (nf_same_as_value _).mpr\n        apply IsValue.const\n  | p t₁ t₂ ih₁ ih₂ =>\n      obtain ⟨t₁', hs₁, hnf₁⟩ := ih₁\n      obtain ⟨t₂', hs₂, hnf₂⟩ := ih₂\n      obtain ⟨n₁⟩ := (nf_same_as_value _).mp hnf₁\n      obtain ⟨n₂⟩ := (nf_same_as_value _).mp hnf₂\n      exists .c (n₁ + n₂)\n      constructor\n      · apply multi_trans _ _ _ _ (multistep_congr_1 t₁ (.c n₁) t₂ hs₁)\n        apply multi_trans _ _ _ _ (multistep_congr_2 (.c n₁) t₂ (.c n₂) (.const n₁) hs₂)\n        apply multi_single\n        apply Step.plus\n      · apply (nf_same_as_value _).mpr\n        apply IsValue.const\n\n\n","context":"Type Systems\u0009Smallstep: Small-step Operational Semantics\u0009Multi-Step Reduction","header":"3.4.2. Normal Forms Again","id":"/Smallstep/#Type-Systems--Smallstep___-Small-step-Operational-Semantics--Multi-Step-Reduction--Normal-Forms-Again"},"/Stlc/#Type-Systems--Stlc___-The-Simply-Typed-Lambda-Calculus--Typing":{"contents":"Next we consider the typing relation of the STLC, which is\nmeant to prevent reduction from getting stuck.\n\n\n\n\n\n\n\n\n\n","context":"Type Systems\u0009Stlc: The Simply Typed Lambda-Calculus","header":"5.4. Typing","id":"/Stlc/#Type-Systems--Stlc___-The-Simply-Typed-Lambda-Calculus--Typing"}});